using System;
using System.Collections.Generic;
using System.Collections.Immutable;
using System.IO;
using System.Linq;
using System.Text;
using Newtonsoft.Json;

namespace RunTests;

/// <summary>
/// The checked in partition configuration for local (non-Helix) runs. This is generated by
/// eng/rebalance-test-partitions.cs and lives at eng/config/test-partitions.json.
/// </summary>
internal sealed class LocalPartitionConfig
{
    [JsonProperty("assemblies")]
    public Dictionary<string, AssemblyPartitionConfig> Assemblies { get; set; } = new(StringComparer.OrdinalIgnoreCase);

    internal static string GetDefaultPath(string artifactsDirectory)
        => Path.Combine(Path.GetDirectoryName(Path.GetFullPath(artifactsDirectory).TrimEnd(Path.DirectorySeparatorChar, Path.AltDirectorySeparatorChar))!, "eng", "config", "test-partitions.json");

    /// <summary>
    /// Load the configuration. Any problem results in a warning and a null return so the caller
    /// falls back to one work item per assembly.
    /// </summary>
    internal static LocalPartitionConfig? TryLoad(string filePath)
    {
        if (!File.Exists(filePath))
        {
            ConsoleUtil.WriteLine(ConsoleColor.Yellow, $"Warning: partition config '{filePath}' not found. Running one work item per assembly.");
            return null;
        }

        try
        {
            var config = JsonConvert.DeserializeObject<LocalPartitionConfig>(File.ReadAllText(filePath));
            if (config is null)
            {
                throw new InvalidOperationException("File is empty");
            }

            // Rebuild the dictionary so lookups are case insensitive regardless of how it was deserialized.
            config.Assemblies = new Dictionary<string, AssemblyPartitionConfig>(config.Assemblies ?? new(), StringComparer.OrdinalIgnoreCase);
            foreach (var (name, assembly) in config.Assemblies)
            {
                foreach (var partition in assembly.Partitions ?? [])
                {
                    if (partition.Prefixes is not { Count: > 0 } prefixes || prefixes.Any(string.IsNullOrWhiteSpace))
                    {
                        throw new InvalidOperationException($"Assembly '{name}' has a partition with no prefixes");
                    }
                }
            }

            return config;
        }
        catch (Exception ex)
        {
            ConsoleUtil.WriteLine(ConsoleColor.Yellow, $"Warning: unable to read partition config '{filePath}': {ex.Message}. Running one work item per assembly.");
            return null;
        }
    }
}

internal sealed class AssemblyPartitionConfig
{
    /// <summary>
    /// Estimated wall clock minutes for the whole assembly. Used to order work items longest first.
    /// </summary>
    [JsonProperty("estimatedMinutes")]
    public double EstimatedMinutes { get; set; }

    /// <summary>
    /// When set the assembly is never partitioned. This documents why splitting would not help
    /// (for example the tests are bound by child processes or I/O rather than CPU).
    /// </summary>
    [JsonProperty("doNotPartitionReason")]
    public string? DoNotPartitionReason { get; set; }

    /// <summary>
    /// Explicit partitions. Every test not matched by one of these runs in an implicit remainder partition.
    /// </summary>
    [JsonProperty("partitions")]
    public List<PartitionConfig>? Partitions { get; set; }

    [JsonProperty("remainderEstimatedMinutes")]
    public double RemainderEstimatedMinutes { get; set; }
}

internal sealed class PartitionConfig
{
    [JsonProperty("estimatedMinutes")]
    public double EstimatedMinutes { get; set; }

    /// <summary>
    /// Namespace or type name prefixes, each ending in '.', matched against the test FullyQualifiedName.
    /// </summary>
    [JsonProperty("prefixes")]
    public List<string> Prefixes { get; set; } = [];
}

internal static class LocalTestPartitioner
{
    /// <summary>
    /// Create the work items for a local run. Assemblies listed in <paramref name="config"/> with partitions
    /// are split using test filters, and the work items are ordered longest estimated duration first so
    /// that the long running assemblies don't form a tail at the end of the run.
    /// </summary>
    internal static ImmutableArray<WorkItemInfo> CreateWorkItems(
        ImmutableArray<AssemblyInfo> assemblies,
        LocalPartitionConfig? config,
        bool allowPartitioning,
        Func<AssemblyInfo, bool> shouldRunInSingleWorkItem)
    {
        var workItems = new List<WorkItemInfo>();
        var partitionIndex = 0;
        foreach (var assembly in assemblies)
        {
            var filters = ImmutableSortedDictionary<AssemblyInfo, ImmutableArray<TestMethodInfo>>.Empty.Add(assembly, ImmutableArray<TestMethodInfo>.Empty);
            var assemblyConfig = TryGetAssemblyConfig(config, assembly);
            var partitions = assemblyConfig?.Partitions;
            if (allowPartitioning &&
                assemblyConfig is not null &&
                partitions is { Count: > 0 } &&
                assemblyConfig.DoNotPartitionReason is null &&
                IsCoreTargetFramework(assembly) &&
                !shouldRunInSingleWorkItem(assembly))
            {
                var count = partitions.Count + 1;
                for (var i = 0; i < partitions.Count; i++)
                {
                    workItems.Add(new WorkItemInfo(filters, partitionIndex++)
                    {
                        TestFilter = BuildIncludeFilter(partitions[i].Prefixes),
                        PartitionName = $"part{i + 1}of{count}",
                        EstimatedMinutes = partitions[i].EstimatedMinutes,
                    });
                }

                workItems.Add(new WorkItemInfo(filters, partitionIndex++)
                {
                    TestFilter = BuildExcludeFilter(partitions.SelectMany(p => p.Prefixes)),
                    PartitionName = $"part{count}of{count}",
                    EstimatedMinutes = assemblyConfig.RemainderEstimatedMinutes,
                });
            }
            else
            {
                workItems.Add(new WorkItemInfo(filters, partitionIndex++)
                {
                    EstimatedMinutes = assemblyConfig?.EstimatedMinutes ?? 0,
                });
            }
        }

        // Longest processing time first. Work items without an estimate keep their relative (name) order at the end.
        return workItems
            .OrderByDescending(w => w.EstimatedMinutes)
            .ThenBy(w => w.PartitionIndex)
            .ToImmutableArray();
    }

    private static AssemblyPartitionConfig? TryGetAssemblyConfig(LocalPartitionConfig? config, AssemblyInfo assembly)
        => config is not null && config.Assemblies.TryGetValue(Path.GetFileNameWithoutExtension(assembly.AssemblyPath), out var assemblyConfig)
            ? assemblyConfig
            : null;

    /// <summary>
    /// The partition configuration is computed from .NET Core runs; desktop runs are not partitioned.
    /// </summary>
    internal static bool IsCoreTargetFramework(AssemblyInfo assembly)
    {
        var tfm = Path.GetFileName(Path.GetDirectoryName(assembly.AssemblyPath)) ?? "";
        return !tfm.StartsWith("net4", StringComparison.OrdinalIgnoreCase);
    }

    internal static string BuildIncludeFilter(IEnumerable<string> prefixes)
        => string.Join("|", prefixes.Select(p => $"FullyQualifiedName~{EscapeFilterValue(p)}"));

    internal static string BuildExcludeFilter(IEnumerable<string> prefixes)
        => string.Join("&", prefixes.Select(p => $"FullyQualifiedName!~{EscapeFilterValue(p)}"));

    /// <summary>
    /// Escape the characters that are significant in a vstest filter expression.
    /// </summary>
    internal static string EscapeFilterValue(string value)
    {
        var builder = new StringBuilder(value.Length);
        foreach (var c in value)
        {
            if (c is '\\' or '(' or ')' or '&' or '|' or '=' or '!' or '~')
            {
                builder.Append('\\');
            }

            builder.Append(c);
        }

        return builder.ToString();
    }
}
